// Exception handling flow (Liang Ch. 14 style)
public class ExceptionExample {
    static int quotient(int number1, int number2) {
        if (number2 == 0) {
            // throw ends this method immediately and starts looking for a matching catch
            throw new ArithmeticException("Divisor cannot be zero");
        }
        return number1 / number2;
    }

    static void runCase(int a, int b) {
        try {
            int result = quotient(a, b);
            System.out.println(a + " / " + b + " = " + result);   // skipped if quotient throws
        } catch (ArithmeticException ex) {
            System.out.println("Handled exception: " + ex.getMessage());
        } finally {
            // runs on both paths: after the try, or after the catch
            System.out.println("Case finished for inputs (" + a + ", " + b + ")");
        }
    }

    public static void main(String[] args) {
        runCase(12, 3);
        runCase(10, 0);
        System.out.println("Execution continues after catch/finally.");
    }
}

