#include <functional>
#include <iostream>
#include <stdexcept>

// C++ has no finally; an object's destructor runs when its scope ends, normally or by exception
struct Finally {
    std::function<void()> action;
    ~Finally() { action(); }
};

int quotient(int number1, int number2) {
    if (number2 == 0) {
        // Integer division by zero is undefined behavior in C++, so we must check and throw ourselves
        throw std::domain_error("Divisor cannot be zero");
    }
    return number1 / number2;
}

void runCase(int a, int b) {
    Finally done{[&] { std::cout << "Case finished for inputs (" << a << ", " << b << ")\n"; }};
    try {
        int result = quotient(a, b);
        std::cout << a << " / " << b << " = " << result << "\n";
    } catch (const std::domain_error& ex) {
        std::cout << "Handled exception: " << ex.what() << "\n";
    }
}  // done's destructor prints here, after the try or the catch

int main() {
    runCase(12, 3);
    runCase(10, 0);
    std::cout << "Execution continues after catch/finally.\n";
}

