public class TryCatchParsing {
    static int parsePercent(String text) {
        int value = Integer.parseInt(text);          // throws NumberFormatException for "abc"
        if (value < 0 || value > 100) {
            throw new IllegalArgumentException("out of range: " + value);
        }
        return value;
    }

    public static void main(String[] args) {
        String[] inputs = {"85", "abc", "150", "40"};
        int total = 0;
        int valid = 0;
        for (String input : inputs) {
            System.out.println("try \"" + input + "\"");
            try {
                int percent = parsePercent(input);
                System.out.println("  parsed " + percent + "%");   // skipped when parsePercent throws
                total += percent;
                valid++;
            } catch (NumberFormatException e) {
                // Must come before its superclass IllegalArgumentException, or it would be unreachable
                System.out.println("  not a number, skipped");
            } catch (IllegalArgumentException e) {
                System.out.println("  rejected: " + e.getMessage());
            }
        }
        System.out.println("valid inputs: " + valid + ", average " + (total / valid) + "%");
    }
}

