public class FinallyAndResources {
    static void normalPath() {
        try {
            System.out.println("try: working");
        } finally {
            System.out.println("finally: cleanup");
        }
    }

    static void exceptionPath() {
        try {
            System.out.println("try: about to throw");
            throw new IllegalStateException("boom");
        } finally {
            System.out.println("finally: cleanup");       // runs while the exception propagates
        }
    }

    static int returnPath() {
        try {
            System.out.println("try: returning 1");
            return 1;
        } finally {
            System.out.println("finally: runs before the caller gets the value");
        }
    }

    public static void main(String[] args) {
        System.out.println("-- normal path");
        normalPath();

        System.out.println("-- exception path");
        try {
            exceptionPath();
        } catch (IllegalStateException e) {
            System.out.println("caller caught: " + e.getMessage());
        }

        System.out.println("-- return path");
        int result = returnPath();
        System.out.println("result = " + result);

        System.out.println("-- try-with-resources");
        // Resources are closed automatically, in reverse order of declaration
        try (Resource a = new Resource("A"); Resource b = new Resource("B")) {
            System.out.println("using A and B");
        }

        try (Resource c = new Resource("C")) {
            throw new IllegalStateException("failure inside body");
        } catch (IllegalStateException e) {
            System.out.println("caught after close: " + e.getMessage());   // C is already closed here
        }
    }
}

class Resource implements AutoCloseable {
    private final String name;

    Resource(String name) {
        this.name = name;
        System.out.println("open " + name);
    }

    @Override
    public void close() {
        System.out.println("close " + name);
    }
}

