// RAII: acquire in the constructor, release in the destructor
class Resource {
    std::string name;

public:
    explicit Resource(std::string n) : name(std::move(n)) { std::cout << "open " << name << "\n"; }
    ~Resource() { std::cout << "close " << name << "\n"; }
};

// C++ has no finally keyword; a guard object's destructor does the same job
struct Finally {
    std::function<void()> action;
    ~Finally() { action(); }
};

void normalPath() {
    Finally cleanup{[] { std::cout << "finally: cleanup\n"; }};
    std::cout << "try: working\n";
}

void exceptionPath() {
    Finally cleanup{[] { std::cout << "finally: cleanup\n"; }};
    std::cout << "try: about to throw\n";
    throw std::logic_error("boom");  // the destructor runs during stack unwinding
}

int returnPath() {
    Finally cleanup{[] { std::cout << "finally: runs before the caller gets the value\n"; }};
    std::cout << "try: returning 1\n";
    return 1;
}

int main() {
    std::cout << "-- normal path\n";
    normalPath();

    std::cout << "-- exception path\n";
    try {
        exceptionPath();
    } catch (const std::logic_error& e) {
        std::cout << "caller caught: " << e.what() << "\n";
    }

    std::cout << "-- return path\n";
    int result = returnPath();
    std::cout << "result = " << result << "\n";

    std::cout << "-- try-with-resources\n";
    {
        Resource a("A");
        Resource b("B");
        std::cout << "using A and B\n";
    }  // destructors run in reverse order of construction: B, then A

    try {
        Resource c("C");
        throw std::logic_error("failure inside body");
    } catch (const std::logic_error& e) {
        std::cout << "caught after close: " << e.what() << "\n";
    }
