#include <cstdio>
#include <exception>
#include <iostream>
#include <stdexcept>
#include <string>

std::string fmt(double v) {
    char buf[32];
    std::snprintf(buf, sizeof buf, "%.2f", v);
    return buf;
}

// Custom exceptions usually derive from std::runtime_error, which stores the message
class InsufficientFundsException : public std::runtime_error {
    double shortfall;

public:
    InsufficientFundsException(const std::string& message, double shortfall)
        : std::runtime_error(message), shortfall(shortfall) {}
    double getShortfall() const { return shortfall; }
};

class TransferFailedException : public std::runtime_error {
public:
    using std::runtime_error::runtime_error;
};

class Wallet {
    double balance;

public:
    explicit Wallet(double balance) : balance(balance) {}
    double getBalance() const { return balance; }

    // C++ has no checked exceptions or throws clause; document what a function may throw
    void withdraw(double amount) {
        if (amount > balance) {
            throw InsufficientFundsException("balance " + fmt(balance) + " is less than " + fmt(amount),
                                             amount - balance);
        }
        balance -= amount;
    }
};

void transfer(Wallet& from, const std::string& to, double amount) {
    try {
        from.withdraw(amount);
    } catch (const InsufficientFundsException&) {
        // throw_with_nested attaches the exception being handled as the "cause"
        std::throw_with_nested(TransferFailedException("could not send " + fmt(amount) + " to " + to));
    }
}

int main() {
    Wallet wallet(100.00);
    try {
        wallet.withdraw(30.00);
        std::cout << "withdraw 30.00 -> ok, balance " << fmt(wallet.getBalance()) << "\n";
        wallet.withdraw(120.00);
        std::cout << "this line is never reached\n";
    } catch (const InsufficientFundsException& e) {
        std::cout << "withdraw 120.00 -> " << e.what() << "\n";
        std::cout << "  shortfall field: " << fmt(e.getShortfall()) << "\n";
    }

    try {
        transfer(wallet, "Sam", 120.00);
    } catch (const TransferFailedException& e) {
        std::cout << "transfer failed: " << e.what() << "\n";
        try {
            std::rethrow_if_nested(e);  // rethrows the nested cause, like getCause()
        } catch (const InsufficientFundsException& cause) {
            std::cout << "  caused by: " << cause.what() << "\n";
            std::cout << "  cause type: InsufficientFundsException\n";
        }
    }
}

