import java.io.FileNotFoundException;
import java.io.IOException;
import java.util.List;
import java.util.Map;

public class ThrowsPropagation {
    // In-memory stand-in for the file system (real code: Files.readString(Path.of(name)))
    static final Map<String, String> FILES = Map.of("app.cfg", "port=8080", "bad.cfg", "port=http");

    // "throws" warns every caller that this checked exception may escape
    static String readConfig(String name) throws IOException {
        System.out.println("    readConfig(\"" + name + "\")");
        String text = FILES.get(name);
        if (text == null) {
            throw new FileNotFoundException(name + " not found");   // "throw" raises it now
        }
        return text;
    }

    // No catch here: declaring throws passes the exception up to our caller
    static int loadPort(String name) throws IOException {
        System.out.println("  loadPort(\"" + name + "\")");
        String text = readConfig(name);
        System.out.println("  parsed " + text);
        return Integer.parseInt(text.substring(text.indexOf('=') + 1));  // unchecked NumberFormatException
    }

    // Handles IOException, so this method needs no throws clause
    static int portOrDefault(String name) {
        try {
            return loadPort(name);
        } catch (IOException e) {
            System.out.println("  portOrDefault caught: " + e.getMessage() + ", using 80");
            return 80;
        }
    }

    public static void main(String[] args) {
        for (String name : List.of("app.cfg", "missing.cfg", "bad.cfg")) {
            System.out.println("portOrDefault(\"" + name + "\")");
            try {
                System.out.println("=> port " + portOrDefault(name));
            } catch (NumberFormatException e) {
                System.out.println("main caught an unchecked exception: port value is not a number");
            }
        }
    }
}

