#include <iostream>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>

// C++ has no checked exceptions and no throws clause (dynamic exception specs were removed in C++17).
// Only "noexcept" can be declared, and it promises the opposite: nothing escapes.
class FileNotFound : public std::runtime_error {
public:
    using std::runtime_error::runtime_error;
};

const std::map<std::string, std::string> FILES = {{"app.cfg", "port=8080"}, {"bad.cfg", "port=http"}};

// may throw FileNotFound
std::string readConfig(const std::string& name) {
    std::cout << "    readConfig(\"" << name << "\")\n";
    auto it = FILES.find(name);
    if (it == FILES.end()) throw FileNotFound(name + " not found");
    return it->second;
}

// may throw FileNotFound or std::invalid_argument
int loadPort(const std::string& name) {
    std::cout << "  loadPort(\"" << name << "\")\n";
    std::string text = readConfig(name);
    std::cout << "  parsed " << text << "\n";
    return std::stoi(text.substr(text.find('=') + 1));
}

int portOrDefault(const std::string& name) {
    try {
        return loadPort(name);
    } catch (const FileNotFound& e) {
        std::cout << "  portOrDefault caught: " << e.what() << ", using 80\n";
        return 80;
    }
}

int main() {
    for (const std::string name : {"app.cfg", "missing.cfg", "bad.cfg"}) {
        std::cout << "portOrDefault(\"" << name << "\")\n";
        try {
            int port = portOrDefault(name);
            std::cout << "=> port " << port << "\n";
        } catch (const std::invalid_argument&) {
            std::cout << "main caught an unchecked exception: port value is not a number\n";
        }
    }
