// JS has no checked exceptions or throws clause; JSDoc @throws documents them instead
const FILES = new Map([['app.cfg', 'port=8080'], ['bad.cfg', 'port=http']]);

class FileNotFoundError extends Error {}

/** @throws {FileNotFoundError} */
function readConfig(name) {
  console.log(`    readConfig("${name}")`);
  if (!FILES.has(name)) throw new FileNotFoundError(`${name} not found`);
  return FILES.get(name);
}

/** @throws {FileNotFoundError|TypeError} */
function loadPort(name) {
  console.log(`  loadPort("${name}")`);
  const text = readConfig(name);
  console.log(`  parsed ${text}`);
  const value = text.slice(text.indexOf('=') + 1);
  if (!/^\d+$/.test(value)) throw new TypeError('not a number'); // Number('http') would be NaN
  return Number(value);
}

function portOrDefault(name) {
  try {
    return loadPort(name);
  } catch (e) {
    if (!(e instanceof FileNotFoundError)) throw e; // let other errors propagate
    console.log(`  portOrDefault caught: ${e.message}, using 80`);
    return 80;
  }
}

for (const name of ['app.cfg', 'missing.cfg', 'bad.cfg']) {
  console.log(`portOrDefault("${name}")`);
  try {
    console.log(`=> port ${portOrDefault(name)}`);
  } catch (e) {
    if (!(e instanceof TypeError)) throw e;
    console.log('main caught an unchecked exception: port value is not a number');
  }
}

