import java.io.FileNotFoundException;
import java.util.List;

public class ExceptionTypesHierarchy {
    // Climb the real class hierarchy with reflection
    static String chain(Class<?> c) {
        StringBuilder sb = new StringBuilder(c.getSimpleName());
        for (Class<?> p = c.getSuperclass(); p != Object.class; p = p.getSuperclass()) {
            sb.append(" -> ").append(p.getSimpleName());
        }
        return sb.toString();
    }

    static String kind(Class<? extends Throwable> c) {
        if (Error.class.isAssignableFrom(c)) return "[error]";
        if (RuntimeException.class.isAssignableFrom(c)) return "[unchecked]";
        return "[checked]";           // any other Exception: the compiler forces catch-or-declare
    }

    public static void main(String[] args) {
        List<Class<? extends Throwable>> types = List.of(
            FileNotFoundException.class, InterruptedException.class,
            ArithmeticException.class, NumberFormatException.class,
            ArrayIndexOutOfBoundsException.class, NullPointerException.class,
            StackOverflowError.class);
        for (Class<? extends Throwable> c : types) {
            System.out.println(String.format("%-11s %s", kind(c), chain(c)));
        }

        int[] data = new int[2];
        try {
            data[5] = 1;              // throws ArrayIndexOutOfBoundsException
        } catch (RuntimeException e) {
            // A catch clause also matches every subclass of the type it names
            System.out.println("bad index -> caught by a handler for its superclass");
        }
    }
}

