#include <stdexcept>
#include <string>
#include <vector>

// C++ has its own hierarchy (std::out_of_range -> std::logic_error -> std::exception) and no
// checked exceptions, so Java's tree is modeled here as a child -> parent map.
const std::map<std::string, std::string> PARENT = {
    {"FileNotFoundException", "IOException"}, {"IOException", "Exception"},
    {"InterruptedException", "Exception"}, {"ArithmeticException", "RuntimeException"},
    {"NumberFormatException", "IllegalArgumentException"}, {"IllegalArgumentException", "RuntimeException"},
    {"ArrayIndexOutOfBoundsException", "IndexOutOfBoundsException"},
    {"IndexOutOfBoundsException", "RuntimeException"}, {"NullPointerException", "RuntimeException"},
    {"RuntimeException", "Exception"}, {"Exception", "Throwable"},
    {"StackOverflowError", "VirtualMachineError"}, {"VirtualMachineError", "Error"}, {"Error", "Throwable"},
};

std::vector<std::string> ancestors(std::string name) {
    std::vector<std::string> path = {name};
    while (PARENT.count(name)) {
        name = PARENT.at(name);
        path.push_back(name);
    }
    return path;
}

std::string kind(const std::vector<std::string>& path) {
    for (const auto& p : path) {
        if (p == "Error") return "[error]";
        if (p == "RuntimeException") return "[unchecked]";
    }
    return "[checked]";
}

int main() {
    std::vector<std::string> types = {"FileNotFoundException", "InterruptedException", "ArithmeticException",
                                      "NumberFormatException", "ArrayIndexOutOfBoundsException",
                                      "NullPointerException", "StackOverflowError"};
    for (const auto& t : types) {
        auto path = ancestors(t);
        std::string chain = path[0];
        for (size_t i = 1; i < path.size(); ++i) chain += " -> " + path[i];
        std::printf("%-11s %s\n", kind(path).c_str(), chain.c_str());
    }

    std::vector<int> data(2);
    try {
        data.at(5) = 1;  // at() throws std::out_of_range ([] would be undefined behavior)
    } catch (const std::logic_error&) {  // the base class handler catches it
        std::printf("bad index -> caught by a handler for its superclass\n");
    }
}

