class Solution {
    static int parseOrDefault(String text, int fallback) {
        if (text == null) return fallback;          // calling trim() on null would throw
        try {
            return Integer.parseInt(text.trim());
        } catch (NumberFormatException e) {         // catch only the failure we expect
            return fallback;
        }
    }
}

